import re
import sys

lines = sys.stdin.read().splitlines()

def compile_pattern(pattern, ignore_case):
    parts = []
    for ch in pattern:
        if ch == '*':
            parts.append('.*')
        elif ch == '?':
            parts.append('.')
        else:
            parts.append(re.escape(ch))
    flags = re.IGNORECASE if ignore_case else 0
    return re.compile('^' + ''.join(parts) + '$', flags)

n = int(lines[0])
statements = []
for line in lines[1:1 + n]:
    action, resource = line.split()
    statements.append((compile_pattern(action, True), compile_pattern(resource, False)))

m = int(lines[1 + n])
for line in lines[2 + n:2 + n + m]:
    action, resource = line.split()
    allowed = any(a.match(action) and r.match(resource) for a, r in statements)
    print(action + ' -> ' + ('ALLOWED' if allowed else 'DENIED'))
